import{_ as a,b as t,f as o,I as l}from"./chunks/framework.DYvp_Vyw.js";const h=JSON.parse('{"title":"Java期末复习笔记 - 第二章 - Java语言开发环境","description":"","frontmatter":{"title":"Java期末复习笔记 - 第二章 - Java语言开发环境","date":"2025-05-07T01:49:13.000Z","tags":["Java"],"head":[["meta",{"name":"descriptionx x x","content":"vitepress-theme-bluearchive Tags"}],["meta",{"name":"keywords","content":"vitepress theme bluearchive Tags"}]]},"headers":[],"relativePath":"posts/Java-Own-Study-002.md","filePath":"posts/Java-Own-Study-002.md"}'),r={name:"posts/Java-Own-Study-002.md"};function n(d,e,i,c,u,s){return o(),t("div",null,e[0]||(e[0]=[l('<p>大二上学期的期末复习笔记。</p><hr><div style="text-align:center;"><h1>Java语言开发环境</h1></div><h1 id="_1-jdk" tabindex="-1"><u style="text-decoration:underline;text-decoration-color:deepskyblue;">1.JDK</u> <a class="header-anchor" href="#_1-jdk" aria-label="Permalink to &quot;&lt;u style=&quot;text-decoration: underline; text-decoration-color: deepskyblue;&quot;&gt;1.JDK&lt;/u&gt;&quot;">​</a></h1><p>1.JDK是许多Java程序员使用的开发环境。其核心是Java API，所谓API就是Java提供的标准类库。</p><p>2.Java API包括一些重要的语言结构以及基本图形，网络和文件I/O等。</p><h1 id="_2-关于jdk安装文件夹" tabindex="-1"><u style="text-decoration:underline;text-decoration-color:deepskyblue;">2.关于JDK安装文件夹</u> <a class="header-anchor" href="#_2-关于jdk安装文件夹" aria-label="Permalink to &quot;&lt;u style=&quot;text-decoration: underline; text-decoration-color: deepskyblue;&quot;&gt;2.关于JDK安装文件夹&lt;/u&gt;&quot;">​</a></h1><h3 id="_1-安装文件夹下的子文件夹" tabindex="-1">1.安装文件夹下的子文件夹 <a class="header-anchor" href="#_1-安装文件夹下的子文件夹" aria-label="Permalink to &quot;1.安装文件夹下的子文件夹&quot;">​</a></h3><pre><code>-  `bin`:该文件夹存放的是JDK指令程序等。\n- `conf`:该文件夹存放的是一些可供开发者编程的java系统配置文件。\n- `include`:该文件夹下存放的是支持本地代码编程与C语言程序的相关头文件。\n- `jmods`:该文件夹存放的是预编译的Java模块，相当于JDK9之前的.jar文件。\n- `legal`:该文件夹下存放的是有关Java每个模块的版权声明和许可协议等。\n- `lib`:该文件夹存放的是Java类库。\n</code></pre><h3 id="_2-bin文件夹下的常用指令" tabindex="-1">2.<code>bin</code>文件夹下的常用指令 <a class="header-anchor" href="#_2-bin文件夹下的常用指令" aria-label="Permalink to &quot;2.`bin`文件夹下的常用指令&quot;">​</a></h3><pre><code>- `javac.exe`:Java编译器，将Java源文件转换为字节码文件。\n- `java.exe`:Java解释器，执行Java程序的字节码文件。\n- `javadoc.exe`:根据Java源代码及注释语句生成Java程序的HTML格式的帮助文档。\n- `javap.exe`:把编译得到的字节码还原为源文件。\n- `jdb.exe`:Java调试器，可以逐行执行程序，设置断点和检查变量。\n- `jar.exe`:创建扩展名为.jar的压缩文件，与zip压缩文件格式相同。\n- `jmod.exe`:创建扩展名为.jmod的压缩文件。\n</code></pre><h1 id="_3-本章小结" tabindex="-1"><u style="text-decoration:underline;text-decoration-color:deepskyblue;">3.本章小结</u> <a class="header-anchor" href="#_3-本章小结" aria-label="Permalink to &quot;&lt;u style=&quot;text-decoration: underline; text-decoration-color: deepskyblue;&quot;&gt;3.本章小结&lt;/u&gt;&quot;">​</a></h1><p>1.在使用Java语言编译与运行程序前，必须先设置系统变量<code>Path</code>，<code>Path</code>系统变量的作用是设置供操作系统去寻找可执行文件的路径的顺序。</p><p>2.Java应用程序源文件的命名规则：</p><ul><li>首先源文件的扩展名必须是.java；</li><li>如果源文件中有多个类，则最多只能有一个public类，如果有的话，那么源文件的名称必须与这个public类的名称相同（大小写可以不同）。</li><li>如果源文件中没有public类，那么源文件的名字由用户任意命名。但需要注意的是，包含有main（）方法的类是应用程序的主类，主类不管是否是public类，执行时必须输入主类名，即“Java 主类名”，因为主类的main（）方法是程序执行的起始点。</li></ul><p>3.<code>main()</code>在Java程序中是一个相当特殊的方法，它一定要声明成public，使得在类的其他能调用它，且<code>main()</code>方法没有返回值，所以在它之前要加上void关键字。</p><p>4.由于Java程序是由类组成的，因此在完整的Java程序中，至少必须有一个类。</p><p>5.当.java源文件所使用的字符集与命令行窗口的编码环境不一样时，在编译源文件时需要在编译指令中给出字符集选项“-encoding 字符集”。</p><h1 id="随堂小测" tabindex="-1"><u style="text-decoration:underline;text-decoration-color:deepskyblue;">随堂小测</u> <a class="header-anchor" href="#随堂小测" aria-label="Permalink to &quot;&lt;u style=&quot;text-decoration: underline; text-decoration-color: deepskyblue;&quot;&gt;随堂小测&lt;/u&gt;&quot;">​</a></h1><p>1.安装JDK时，为了能方便地编译和运行程序，应该设置环境变量变量的名称是（）。 A.JAVAHOME B.java C.Path D.classpath</p><p>2.下列说法不正确的是（）。 A.一个Java源程序经过编译后，得到的文件扩展名一定是class。 B.一个Java源程序编译通过后，得到的结果文件数也只有一个。 C.一个Java源程序编译通过后，得到的结果文件数可能有多个。 D.一个Java源程序编译通过后，不一定能用Java解释器执行。</p><h1 id="答案" tabindex="-1"><u style="text-decoration:underline;text-decoration-color:deepskyblue;">答案</u> <a class="header-anchor" href="#答案" aria-label="Permalink to &quot;&lt;u style=&quot;text-decoration: underline; text-decoration-color: deepskyblue;&quot;&gt;答案&lt;/u&gt;&quot;">​</a></h1><p>1-2 CB</p><h1 id="解析" tabindex="-1"><u style="text-decoration:underline;text-decoration-color:deepskyblue;">解析：</u> <a class="header-anchor" href="#解析" aria-label="Permalink to &quot;&lt;u style=&quot;text-decoration: underline; text-decoration-color: deepskyblue;&quot;&gt;解析：&lt;/u&gt;&quot;">​</a></h1><h3 id="_2" tabindex="-1">2. <a class="header-anchor" href="#_2" aria-label="Permalink to &quot;2.&quot;">​</a></h3><ul><li><p><strong>A. 一个Java源程序经过编译后，得到的文件扩展名一定是class。</strong><br> 正确。Java 源文件编译后生成的字节码文件扩展名确实是 <code>.class</code>。</p></li><li><p><strong>B. 一个Java源程序编译通过后，得到的结果文件数也只有一个。</strong><br> 不正确。一个 Java 源文件可以包含多个类，因此编译后可能会生成多个 <code>.class</code> 文件。</p></li><li><p><strong>C. 一个Java源程序编译通过后，得到的结果文件数可能有多个。</strong><br> 正确。若源文件中定义了多个类，则会生成多个 <code>.class</code> 文件。</p></li><li><p><strong>D. 一个Java源程序编译通过后，不一定能用Java解释器执行。</strong><br> 正确。编译后的 <code>.class</code> 文件可能由于某些原因（如缺少依赖或错误的类路径）而无法执行。</p></li></ul><hr>',27)]))}const v=a(r,[["render",n]]);export{h as __pageData,v as default};
